// ===== 07-matcap-bomb: матчеп бомбы (ассет владельца) =====
// «3d assets/matcap/bomb.png» (512×512), инлайн base64 — сборка обязана
// открываться ОДНИМ файлом офлайн, внешних запросов у неё нет.
// ⚠️⚠️ ЭТИМ ОТМЕНЁН ПРОЦЕДУРНЫЙ РАДУЖНЫЙ МАТЧЕП БОМБЫ (`bombMatcap` в
// 40-items, слово владельца 2026-08-17-ж: «возьми для бомбы»). Прежний пёкся
// кодом, потому что three r149 не умеет `MeshPhysicalMaterial.iridescence`;
// причина никуда не делась, но картинку теперь даёт владелец, и это сильнее
// любой процедурной подделки.
// ⚠️ НОМЕР < 20 — ПО ТОЙ ЖЕ ПРИЧИНЕ, ЧТО У 06: функции хойстятся, а `const`
// из старших модулей в TDZ для top-level кода младших (инцидент 2026-08-13).
// ⚠️ ЦЕНА НАЗВАНА: 121 КБ PNG -> ~162 КБ base64 в index.html.
// Ассет владельца берём КАК ЕСТЬ, без пережатия и без смены расширения.
const MATCAP_BOMB_PNG = 'data:image/png;base64,';
let _bombMatcapTex = null;
// Загрузка тем же приёмом, что у палитровых атласов и у матчепа металла:
// белая 1×1 заглушка до декода, подмена источника по onload. Без заглушки
// первые кадры выборка даёт нули, и материал вспыхивает чёрным.
function bombMatcapTex(){
  if (_bombMatcapTex) return _bombMatcapTex;
  const stub = document.createElement('canvas');
  stub.width = stub.height = 1;
  const g = stub.getContext('2d');
  g.fillStyle = '#fff'; g.fillRect(0, 0, 1, 1);
  const t = new THREE.Texture(stub);
  t.encoding = THREE.sRGBEncoding;
  t.magFilter = t.minFilter = THREE.LinearFilter;
  t.generateMipmaps = false;
  const img = new Image();
  img.onload = () => { t.image = img; t.needsUpdate = true; };
  img.src = MATCAP_BOMB_PNG;
  _bombMatcapTex = t;
  return t;
}
